161: static void spacemit_i2c_unit_init(struct spacemit_i2c_dev *spacemit_i2c)
162: {
163: 	rt_uint32_t cr_val = 0;
164: 
165: 	/*
166: 	 * Unmask interrupt bits for all xfer mode:
167: 	 * bus error, arbitration loss detected.
168: 	 * For transaction complete signal, we use master stop
169: 	 * interrupt, so we don't need to unmask CR_TXDONEIE.
170: 	 */
171: 	cr_val |= CR_BEIE | CR_ALDIE;
172: 
173: 	if (spacemit_i2c->xfer_mode == SPACEMIT_I2C_MODE_INTERRUPT)
174: 		/*
175: 		 * Unmask interrupt bits for interrupt xfer mode:
176: 		 * DBR rx full.
177: 		 * For tx empty interrupt CR_DTEIE, we only
178: 		 * need to enable when trigger byte transfer to start
179: 		 * data sending.
180: 		 */
181: 		cr_val |= CR_DRFIE;
182: 	else if (spacemit_i2c->xfer_mode == SPACEMIT_I2C_MODE_FIFO)
183: 		/* enable i2c FIFO mode*/
184: 		cr_val |= CR_FIFOEN;
185: 
186: 	/* set speed bits */
187: 	if (spacemit_i2c->fast_mode)
188: 		cr_val |= CR_MODE_FAST;
189: 	if (spacemit_i2c->high_mode)
190: 		cr_val |= CR_MODE_HIGH | CR_GPIOEN;
191: 
192: 	/* disable response to general call */
193: 	cr_val |= CR_GCD;
194: 
195: 	/* enable SCL clock output */
196: 	cr_val |= CR_SCLE;
197: 
198: 	/* enable master stop detected */
199: 	cr_val |= CR_MSDE | CR_MSDIE;
200: 
201: 	spacemit_i2c_write_reg(spacemit_i2c, REG_CR, cr_val);
202: 
203: 	/*
204: 	 * The K1 I2C controller has an SDA glitch fix which can suppress short
205: 	 * pulses on SDA, but it may also introduce a small delay on restart
206: 	 * (repeated-start) signals on some systems.
207: 	 */
208: 	if (spacemit_i2c->sda_glitch_nofix) {
209: 		rt_uint32_t rcr_val = spacemit_i2c_read_reg(spacemit_i2c, REG_RST_CYC);
210: 		rcr_val |= RCR_SDA_GLITCH_NOFIX;
211: 		spacemit_i2c_write_reg(spacemit_i2c, REG_RST_CYC, rcr_val);
212: 	}
213: }
