623: static void spacemit_i2c_int_handler(int irq, void *devid)
624: {
625: 	struct spacemit_i2c_dev *spacemit_i2c = devid;
626: 	rt_uint32_t status, ctrl;
627: 	int ret = 0;
628: 
629: 	/* record i2c status */
630: 	status = spacemit_i2c_read_reg(spacemit_i2c, REG_SR);
631: 	spacemit_i2c->i2c_status = status;
632: 
633: 	/* check if a valid interrupt status */
634: 	if(!status) {
635: 		/* nothing need be done */
636: 		return;
637: 	}
638: 
639: 	/* bus error, rx overrun, arbitration lost */
640: 	spacemit_i2c->i2c_err = status & (SR_BED | SR_RXOV | SR_ALD);
641: 
642: 	/* clear interrupt status bits[31:18]*/
643: 	spacemit_i2c_clear_int_status(spacemit_i2c, status);
644: 
645: 	/* i2c error happens */
646: 	if (spacemit_i2c->i2c_err)
647: 		goto err_out;
648: 
649: 	/* process interrupt mode */
650: 	if (spacemit_i2c->xfer_mode == SPACEMIT_I2C_MODE_INTERRUPT)
651: 		ret = spacemit_i2c_byte_xfer(spacemit_i2c);
652: 
653: err_out:
654: 	/*
655: 	 * send transaction complete signal:
656: 	 * error happens, detect master stop
657: 	 */
658: 	if (spacemit_i2c->i2c_err || (ret < 0) || ((status & SR_MSD) && !(status & SR_ITE))) {
659: 		/*
660: 		 * Here the transaction is already done, we don't need any
661: 		 * other interrupt signals from now, in case any interrupt
662: 		 * happens before spacemit_i2c_xfer to disable irq and i2c unit,
663: 		 * we mask all the interrupt signals and clear the interrupt
664: 		 * status.
665: 		*/
