671: 
672: 		rt_completion_done(&spacemit_i2c->complete);
673: 	} else if ((status & SR_MSD) && (status & SR_ITE)) {
674: 		if (spacemit_i2c->tx_cnt > 1) {
675: 			ctrl = spacemit_i2c_read_reg(spacemit_i2c, REG_CR);
