39: static int adma_irq_handler(int irq, void *arg)
40: {
41: 	unsigned int pending;
42: 
43: 	/* clear pending */
44: 	pending = *((volatile unsigned long *)(ADMA_CHAN_ISR));
45: 	*((volatile unsigned long *)(ADMA_CHAN_ISR)) = 0x0;
46: 
47: 	/* finish transfer */
48: 	if (pending & (1 << 0)) {
49: 		rt_sem_release(trigger_sem);
50: 	}
51: 
52: 	return METAL_IRQ_HANDLED;
53: }
